import{_ as o,o as s,c as r,ae as t}from"./chunks/framework.Dh1jimFm.js";const g=JSON.parse('{"title":"Glossary Search","description":"","frontmatter":{},"headers":[],"relativePath":"superlookup/glossary-search.md","filePath":"superlookup/glossary-search.md"}'),a={name:"superlookup/glossary-search.md"};function l(i,e,n,c,h,u){return s(),r("div",null,e[0]||(e[0]=[t('<h1 id="glossary-search" tabindex="-1">Glossary Search <a class="header-anchor" href="#glossary-search" aria-label="Permalink to &quot;Glossary Search&quot;">​</a></h1><p>Superlookup’s <strong>Glossaries</strong> tab searches your Supervertaler glossaries (termbases) for preferred terminology.</p><h2 id="open-it" tabindex="-1">Open it <a class="header-anchor" href="#open-it" aria-label="Permalink to &quot;Open it&quot;">​</a></h2><ul><li><strong>In Supervertaler:</strong> press <code>Ctrl+K</code>.</li><li>Or open Superlookup from the menu: <strong>Edit → Superlookup…</strong> (<code>Ctrl+Alt+L</code>).</li></ul><h2 id="how-to-search" tabindex="-1">How to search <a class="header-anchor" href="#how-to-search" aria-label="Permalink to &quot;How to search&quot;">​</a></h2><ol><li>Type (or paste) a term into the search box.</li><li>Press <code>Enter</code> (or click <strong>Search</strong>).</li><li>Optional filters: <ul><li><strong>Direction:</strong> Both / Source / Target</li><li><strong>From / To:</strong> filter by glossary language pair (leave as <strong>Any</strong> to search across languages)</li></ul></li></ol><h2 id="what-you-ll-see" tabindex="-1">What you’ll see <a class="header-anchor" href="#what-you-ll-see" aria-label="Permalink to &quot;What you’ll see&quot;">​</a></h2><p>Results are shown in a table with:</p><ul><li><strong>Source</strong></li><li><strong>Target</strong></li><li><strong>Termbase</strong> (glossary name)</li><li><strong>Domain</strong></li><li><strong>Notes</strong></li></ul><p>The current search term is highlighted in the results.</p><h2 id="actions" tabindex="-1">Actions <a class="header-anchor" href="#actions" aria-label="Permalink to &quot;Actions&quot;">​</a></h2><ul><li><strong>Double-click</strong> a row to copy the translation.</li><li><strong>Copy Translation</strong> copies the selected target term.</li><li><strong>Add to Glossary</strong> opens a dialog to add a new term pair (you’ll be prompted to pick a writable glossary).</li></ul><h2 id="edit-in-glossary-jump-to-the-entry" tabindex="-1">Edit in Glossary (jump to the entry) <a class="header-anchor" href="#edit-in-glossary-jump-to-the-entry" aria-label="Permalink to &quot;Edit in Glossary (jump to the entry)&quot;">​</a></h2><p>Right-click a result to open a context menu with:</p><ul><li><strong>Edit in Glossary: …</strong></li></ul><p>This navigates to <strong>Project resources → Glossaries</strong>, selects the glossary, and filters the terms list to the source term.</p><h2 id="glossary-selection" tabindex="-1">Glossary selection <a class="header-anchor" href="#glossary-selection" aria-label="Permalink to &quot;Glossary selection&quot;">​</a></h2><p>In <strong>Superlookup → Settings → Termbases</strong>, you can pick which glossaries Superlookup searches.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>If you don’t select any glossaries in the Superlookup Settings tab, Superlookup searches <strong>all available</strong> glossaries.</p></div>',19)]))}const d=o(a,[["render",l]]);export{g as __pageData,d as default};
